// clause renders the filter as a WHERE fragment with positional arguments.
func (f ListFilter) clause() (string, []any) {
	conditions := []string{}
	args := []any{}
	if f.Component != nil {
		conditions = append(conditions, "component = ?")
		args = append(args, *f.Component)
	}
	if f.Severity != nil {
